proguardAdditions.insert:

-keep class com.taptap.sdk.relation.** { *; }
-keep interface com.taptap.sdk.relation.** { *; }
-keep class com.taptap.sdk.relation.unity.** { *; }
-keepclassmembers class com.taptap.sdk.relation.unity.** { *; }
-keepclasseswithmembernames class * { native <methods>; }

gameActivityClassAdditions.insert:

private BridgeRelationServiceImpl mRelationService;

private BridgeRelationServiceImpl getRelationService() {
    if (mRelationService == null) { mRelationService = new BridgeRelationServiceImpl(); }
    return mRelationService;
}

public void routeToTapRelation(String requestJson, EngineBridgeCallback callback) {
    try {
        org.json.JSONObject req = new org.json.JSONObject(requestJson);
        String method  = req.getString("method");
        String argsStr = req.optString("args", "");
        switch (method) {
            case "prepare":                getRelationService().prepare(); break;
            case "startMessenger":         getRelationService().startMessenger(); break;
            case "inviteGame":             getRelationService().inviteGame(); break;
            case "inviteTeam":
                getRelationService().inviteTeam(new org.json.JSONObject(argsStr).getString("teamId")); break;
            case "showTapUserProfile": {
                org.json.JSONObject a = new org.json.JSONObject(argsStr);
                getRelationService().showTapUserProfile(a.getString("openId"), a.getString("unionId")); break;
            }
            case "getNewFansCount":        getRelationService().getNewFansCount(callback); break;
            case "getUnreadMessageCount":  getRelationService().getUnreadMessageCount(callback); break;
            case "registerRelationCallback": getRelationService().registerRelationCallback(callback); break;
            case "unregisterRelationCallback": getRelationService().unregisterRelationCallback(); break;
            case "registerRelationInviteCallback": getRelationService().registerRelationInviteCallback(callback); break;
            case "unregisterRelationInviteCallback": getRelationService().unregisterRelationInviteCallback(); break;
            case "destroy":                getRelationService().destroy(); break;
            default:
                android.util.Log.w("TapSDK_UE", "TapRelation: unknown method: " + method);
        }
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapRelation route error: " + e.getMessage(), e);
    }
}
